/*
 * Raya core — the Tailwind v4 bridge + component classes shared by every System.
 * Consumers: import AFTER `@import "tailwindcss"` in styles.css, before any System stylesheet.
 * Knob vars (`--raya-<component>-*`) are set per System; fallbacks match the default System.
 */

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --font-sans: var(--font-sans);
  --font-serif: var(--font-serif);
  --font-mono: var(--font-mono);
}

/* ---- button ---- */

.raya-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  height: var(--raya-button-height, 2.25rem);
  padding-inline: var(--raya-button-px, 1rem);
  font-size: var(--raya-button-font-size, 0.875rem);
  font-family: var(--font-sans, ui-sans-serif, system-ui);
  font-weight: 500;
  background: var(--raya-button-bg, var(--primary));
  color: var(--raya-button-fg, var(--primary-foreground));
  border: 1px solid var(--raya-button-border, transparent);
  border-radius: var(--radius-md, 0.375rem);
  cursor: pointer;
  white-space: nowrap;
  transition: opacity 120ms ease, background-color 120ms ease;
}
.raya-button:hover { opacity: 0.9; }
.raya-button:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
.raya-button:disabled, .raya-button[data-disabled] { opacity: 0.5; pointer-events: none; }

/* ---- input / textarea / select ---- */

.raya-input, .raya-textarea, .raya-select-trigger {
  width: 100%;
  font-family: var(--font-sans, ui-sans-serif, system-ui);
  background: var(--background);
  color: var(--foreground);
  border: 1px solid var(--input);
  border-radius: var(--radius-md, 0.375rem);
  outline: none;
}
.raya-input {
  height: var(--raya-input-height, 2.25rem);
  padding-inline: var(--raya-input-padding-x, 0.875rem);
  font-size: var(--raya-input-font-size, 0.875rem);
}
.raya-textarea {
  min-height: var(--raya-textarea-height, 4.5rem);
  padding: calc(var(--raya-textarea-padding-x, 0.875rem) * 0.75) var(--raya-textarea-padding-x, 0.875rem);
  font-size: var(--raya-textarea-font-size, 0.875rem);
  resize: vertical;
}
.raya-select-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  height: var(--raya-select-height, 2.25rem);
  padding-inline: var(--raya-select-padding-x, 0.875rem);
  font-size: var(--raya-select-font-size, 0.875rem);
  background: var(--raya-select-bg, var(--background));
  border-color: var(--raya-select-border, var(--input));
  cursor: pointer;
}
.raya-input:focus-visible, .raya-textarea:focus-visible, .raya-select-trigger:focus-visible {
  border-color: var(--ring);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring) 30%, transparent);
}
.raya-input::placeholder, .raya-textarea::placeholder { color: var(--muted-foreground); }
.raya-input:disabled, .raya-textarea:disabled { opacity: 0.5; cursor: not-allowed; }

.raya-select-positioner, .raya-menu-positioner, .raya-popover-positioner, .raya-tooltip-positioner {
  z-index: 50;
}
.raya-select-content, .raya-menu-content, .raya-popover-content {
  min-width: var(--raya-menu-min-width, 10rem);
  background: var(--popover);
  color: var(--popover-foreground);
  border: 1px solid var(--border);
  border-radius: var(--radius-md, 0.375rem);
  box-shadow: var(--raya-shadow-md, none);
  overflow: hidden;
}

/* ---- checkbox / switch / radio / slider ---- */

.raya-checkbox {
  width: var(--raya-checkbox-size, 1.125rem);
  height: var(--raya-checkbox-size, 1.125rem);
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--background);
  border: 1px solid var(--input);
  border-radius: calc(var(--radius-sm, 0.25rem));
  cursor: pointer;
}
.raya-checkbox[data-checked] { background: var(--primary); border-color: var(--primary); color: var(--primary-foreground); }

.raya-switch {
  display: inline-flex;
  align-items: center;
  width: var(--raya-switch-width, 2.375rem);
  height: var(--raya-switch-height, 1.375rem);
  padding: 2px;
  background: var(--input);
  border-radius: 9999px;
  cursor: pointer;
  transition: background-color 150ms ease;
}
.raya-switch[data-checked] { background: var(--primary); }
.raya-switch-thumb {
  width: calc(var(--raya-switch-height, 1.375rem) - 6px);
  height: calc(var(--raya-switch-height, 1.375rem) - 6px);
  background: var(--background);
  border-radius: 9999px;
  transition: translate 150ms ease;
}
.raya-switch[data-checked] .raya-switch-thumb { translate: calc(var(--raya-switch-width, 2.375rem) - var(--raya-switch-height, 1.375rem)) 0; }

.raya-radio {
  width: var(--raya-radio-size, 1.125rem);
  height: var(--raya-radio-size, 1.125rem);
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--background);
  border: 1px solid var(--input);
  border-radius: 9999px;
  cursor: pointer;
}
.raya-radio-indicator {
  width: 45%;
  height: 45%;
  border-radius: 9999px;
  background: var(--primary);
}
.raya-radio[data-checked] { border-color: var(--primary); }

.raya-slider-root { position: relative; display: flex; align-items: center; width: 100%; }
.raya-slider-track {
  position: relative;
  flex: 1;
  height: 0.375rem;
  background: var(--muted);
  border-radius: 9999px;
}
.raya-slider-range {
  position: absolute;
  inset-block: 0;
  background: var(--primary);
  border-radius: inherit;
}
.raya-slider-thumb {
  width: var(--raya-slider-thumb-size, 1.125rem);
  height: var(--raya-slider-thumb-size, 1.125rem);
  background: var(--background);
  border: 2px solid var(--primary);
  border-radius: 9999px;
  cursor: grab;
}

/* ---- field / label ---- */

.raya-field { display: flex; flex-direction: column; gap: 0.375rem; font-family: var(--font-sans, ui-sans-serif, system-ui); }
.raya-label {
  font-size: var(--raya-field-label-size, 0.8125rem);
  font-weight: 500;
  color: var(--foreground);
}
.raya-field-description { font-size: calc(var(--raya-field-label-size, 0.8125rem) - 0.0625rem); color: var(--muted-foreground); }
.raya-field-error { font-size: calc(var(--raya-field-label-size, 0.8125rem) - 0.0625rem); color: var(--destructive); }

/* ---- card ---- */

.raya-card {
  display: flex;
  flex-direction: column;
  gap: var(--raya-card-gap, 1rem);
  padding: var(--raya-card-padding, 1.5rem);
  font-family: var(--font-sans, ui-sans-serif, system-ui);
  background: var(--card);
  color: var(--card-foreground);
  border: 1px solid var(--raya-card-border-color, var(--border));
  border-radius: var(--radius-lg, 0.625rem);
  box-shadow: var(--raya-card-shadow, none);
}
.raya-card-title { font-size: 1.0625rem; font-weight: 600; line-height: 1.3; }
.raya-card-description { font-size: 0.875rem; color: var(--muted-foreground); }

/* ---- badge ---- */

.raya-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  width: fit-content;
  padding-inline: var(--raya-badge-px, 0.625rem);
  padding-block: var(--raya-badge-py, 0.25rem);
  font-size: var(--raya-badge-font-size, 0.75rem);
  line-height: 1;
  font-weight: 500;
  background: var(--raya-badge-bg, var(--primary));
  color: var(--raya-badge-fg, var(--primary-foreground));
  border: 1px solid var(--raya-badge-border, transparent);
  border-radius: 9999px;
}

/* ---- avatar ---- */

.raya-avatar {
  width: var(--raya-avatar-size, 2rem);
  height: var(--raya-avatar-size, 2rem);
  border-radius: var(--raya-avatar-radius, 9999px);
  background: var(--accent);
  color: var(--accent-foreground);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: calc(var(--raya-avatar-size, 2rem) * 0.375);
  font-weight: 600;
  overflow: hidden;
  flex: none;
}
.raya-avatar-image { width: 100%; height: 100%; object-fit: cover; }

/* ---- tabs ---- */

.raya-tabs-list {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  background: var(--raya-tabs-list-bg, transparent);
  padding: var(--raya-tabs-list-padding, 0);
  border-radius: var(--raya-tabs-list-radius, 0);
  font-family: var(--font-sans, ui-sans-serif, system-ui);
}
.raya-tab {
  display: inline-flex;
  align-items: center;
  padding: var(--raya-tabs-item-padding-y, 0.5rem) var(--raya-tabs-item-padding-x, 1rem);
  font-size: var(--raya-tabs-font-size, 0.875rem);
  color: var(--muted-foreground);
  background: transparent;
  border-radius: var(--raya-tabs-active-radius, 9999px);
  box-shadow: var(--raya-tabs-active-underline, 0 0 #0000);
  cursor: pointer;
  transition: color 120ms ease, background-color 120ms ease;
}
.raya-tab:hover { color: var(--foreground); }
.raya-tab[data-selected], .raya-tab[aria-selected="true"] {
  background: var(--raya-tabs-active-bg, var(--primary));
  color: var(--raya-tabs-active-fg, var(--primary-foreground));
}
.raya-tabs-panel:focus-visible, .raya-tab:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

/* ---- dialog ---- */

.raya-dialog-backdrop, .raya-dialog-popup { animation-duration: 150ms; }
.raya-dialog-popup {
  width: calc(100vw - 2rem);
  max-width: var(--raya-dialog-max-width, 32rem);
  background: var(--popover);
  color: var(--popover-foreground);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg, 0.625rem);
  box-shadow: var(--raya-shadow-lg, none);
  padding: var(--raya-card-padding, 1.5rem);
  display: flex;
  flex-direction: column;
  gap: var(--raya-card-gap, 1rem);
}
.raya-dialog-title { font-size: 1.0625rem; font-weight: 600; }
.raya-dialog-description { font-size: 0.875rem; color: var(--muted-foreground); }

/* ---- dropdown menu ---- */

.raya-menu-content { padding-block: var(--raya-menu-gap, 0.125rem); }
.raya-menu-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: var(--raya-menu-padding-y, 0.375rem) 0.625rem;
  margin-inline: var(--raya-menu-gap, 0.125rem);
  font-size: 0.875rem;
  border-radius: var(--radius-sm, 0.25rem);
  cursor: pointer;
  user-select: none;
}
.raya-menu-item[data-highlighted] { background: var(--accent); color: var(--accent-foreground); }
.raya-menu-item[data-disabled] { opacity: 0.5; pointer-events: none; }
.raya-menu-separator { height: 1px; background: var(--border); margin-block: 0.25rem; }
.raya-menu-group-label {
  padding: var(--raya-menu-padding-y, 0.375rem) 0.625rem;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted-foreground);
}

/* ---- popover / tooltip ---- */

.raya-popover-content { padding: 1rem; width: max-content; max-width: 20rem; }

.raya-tooltip-content {
  padding: 0.3125rem 0.625rem;
  font-size: 0.8125rem;
  line-height: 1.2;
  background: var(--raya-tooltip-bg, var(--foreground));
  color: var(--raya-tooltip-fg, var(--background));
  border-radius: var(--radius-sm, 0.25rem);
}

/* ---- data table ---- */

.raya-table { width: 100%; border-collapse: collapse; font-family: var(--font-sans, ui-sans-serif, system-ui); font-size: var(--raya-table-font-size, 0.875rem); }
.raya-table th, .raya-table td {
  text-align: left;
  padding-block: var(--raya-table-cell-py, 0.625rem);
  padding-inline: 0.75rem;
  border-bottom: 1px solid var(--border);
}
.raya-table th {
  font-size: calc(var(--raya-table-font-size, 0.875rem) - 0.0625rem);
  font-weight: 600;
  color: var(--muted-foreground);
}
.raya-table tbody tr:nth-child(even) { background: var(--raya-table-stripe-bg, transparent); }
.raya-table tbody tr[data-selected] { background: var(--accent); }
.raya-table-sort { cursor: pointer; user-select: none; }
.raya-table-sort:hover { color: var(--foreground); }

/* ---- kpi card ---- */

.raya-kpi {
  display: flex;
  flex-direction: column;
  gap: var(--raya-kpi-gap, 0.75rem);
  padding: var(--raya-kpi-padding, 1.25rem);
  font-family: var(--font-sans, ui-sans-serif, system-ui);
  background: var(--card);
  color: var(--card-foreground);
  border: 1px solid var(--raya-kpi-border-color, var(--border));
  border-radius: var(--radius-lg, 0.625rem);
  box-shadow: var(--raya-kpi-shadow, none);
}
.raya-kpi-label { font-size: 0.8125rem; font-weight: 500; color: var(--muted-foreground); }
.raya-kpi-value { font-size: 1.75rem; font-weight: 650; line-height: 1.1; letter-spacing: -0.01em; }
.raya-kpi-delta { font-size: 0.8125rem; font-weight: 500; }
.raya-kpi-delta[data-direction="up"] { color: oklch(0.55 0.15 150); }
.raya-kpi-delta[data-direction="down"] { color: var(--destructive); }

/* ---- charts ---- */

.raya-chart { font-family: var(--font-sans, ui-sans-serif, system-ui); font-size: 0.8125rem; color: var(--muted-foreground); }
.raya-chart-legend {
  display: var(--raya-chart-legend-display, none);
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}
.raya-chart-legend-item { display: inline-flex; align-items: center; gap: 0.375rem; }
.raya-chart-legend-swatch { width: 0.625rem; height: 0.625rem; border-radius: 2px; background: var(--swatch, var(--chart-1)); }
.raya-chart svg .recharts-cartesian-grid { visibility: var(--raya-chart-grid-visibility, visible); }
.raya-chart-tooltip {
  background: var(--popover);
  color: var(--popover-foreground);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm, 0.25rem);
  box-shadow: var(--raya-shadow-sm, none);
  padding: 0.5rem 0.625rem;
}

/* ---- filter bar (block) ---- */

.raya-filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--raya-filterbar-gap, 0.75rem);
  padding: var(--raya-filterbar-padding, 0.75rem);
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md, 0.375rem);
  font-family: var(--font-sans, ui-sans-serif, system-ui);
}
